select ra_type, count(*), count(*) filter (where risk_class='HIGH') from pd.val_risk_item ri join pd.val_risk_assessment r using(ra_id) group by 1;
select ptype, count(*) from pd.val_protocol group by 1;
select link_type, src_type, tgt_type, count(*) from pd.trace_link group by 1,2,3 order by 1,2,3;
select sys_class, count(*) from pd.val_system group by 1;
